import{_ as a,c as t,o as n,a3 as o}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Advanced configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/advanced-configuration/index.md","filePath":"master/supply-chain/manufacturing/advanced-configuration/index.md","lastUpdated":1793074831000}'),r={name:"master/supply-chain/manufacturing/advanced-configuration/index.md"};function s(i,e,d,l,c,p){return n(),t("div",null,e[0]||(e[0]=[o(`<h1 id="advanced-configuration" tabindex="-1">Advanced configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced configuration&quot;">​</a></h1><p>Basic setup gets a product built. Advanced configuration describes how the work is done on the shop floor: where each step runs, how long it takes, in which order, and which parts of a bill of materials apply to which variant.</p><blockquote><p><strong>In simple words:</strong> Work centers are the places, operations are the steps, and dependencies are the order.</p></blockquote><p>Open <code>Manufacturing → Configurations</code>.</p><div class="info custom-block"><p class="custom-block-title">Gate</p><p><strong>Work Centers</strong> and <strong>Operations</strong> only appear when <strong>Work Orders</strong> is on in <code>Manufacturing → Settings → Manage Operations</code>. Dependencies need <strong>Work Order Dependencies</strong> too. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p></div><h2 id="how-the-pieces-fit-together" tabindex="-1">How the pieces fit together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the pieces fit together&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Work center  (a place: Assembly Station)</span></span>
<span class="line"><span>     ^</span></span>
<span class="line"><span>Operation    (a step on a BoM: Assemble Components)</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Bill of materials  (BOM-MC-LAPTOP)</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Manufacturing order  -&gt;  one work order per operation</span></span></code></pre></div><p>Each operation belongs to one BoM and runs at one work center. When you confirm a manufacturing order, Aureus creates one work order for every operation of its BoM.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./work-centers.html">Work centers</a></td><td>Create a work center, set its working hours, capacity, efficiency and cost per hour.</td></tr><tr><td><a href="./operations.html">Operations</a></td><td>Define routing steps, their duration, worksheet and work center.</td></tr><tr><td><a href="./work-order-dependencies.html">Work order dependencies</a></td><td>Make one step wait for another.</td></tr><tr><td><a href="./bom-variants.html">BoM variants</a></td><td>Use a component or step for chosen variants only.</td></tr></tbody></table><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Create the work centers.</li><li>Create the operations and attach each one to a BoM and a work center.</li><li>Create a manufacturing order and watch the work orders appear.</li></ol><p>The sample data in this guide has two work centers, <strong>Assembly Station</strong> and <strong>Quality &amp; Packing</strong>. It also has two operations, <strong>Assemble Components</strong> and <strong>Test &amp; Pack</strong>, both on <strong>BOM-MC-LAPTOP</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li><li><a href="./../workflows/work-orders.html">Work orders</a></li><li><a href="./../workflows/plan-and-schedule.html">Plan and schedule</a></li></ul>`,15)]))}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
